// 비어 있지 않은 항목의 n 값을 모은다. a가 1이면 대문자로 바꾼다.
function proc(items) {
  return items
    .filter((item) => item != null) // null과 undefined를 모두 거른다
    .map((item) => (item.a == 1 ? item.n.toUpperCase() : item.n));
}

// 쉼표로 구분된 문자열을 앞뒤 공백을 없앤 값 목록으로 바꾸고 빈 값은 버린다.
function f2(text) {
  return text
    .split(',')
    .map((part) => part.trim())
    .filter((part) => part !== '');
}

module.exports = { proc, f2 };

